    return async (req, res, next) => {
        try {
            const userId = req.headers.userid; // In production, get this from a JWT token
            if (!userId) return res.status(401).json({ message: 'Unauthorized: No user ID provided.' });

            // 1. Get the user's role_id
            const [user] = await db.query('SELECT role_id FROM Employee WHERE id = ?', [userId]);
            if (!user) return res.status(404).json({ message: 'User not found.' });

            // 2. Check if the user's role has the required permission
            const [permission] = await db.query(`
                SELECT p.name 
                FROM Role_Permissions rp
                JOIN Permissions p ON rp.permission_id = p.id
                WHERE rp.role_id = ? AND p.name = ?
            `, [user.role_id, requiredPermission]);

            if (!permission) {
                return res.status(403).json({ message: `Forbidden: Missing permission '${requiredPermission}'.` });
            }

            // Permission granted, proceed to the next middleware/route
            next();
        } catch (err) {
            console.error(err);
            return res.status(500).json({ message: 'Internal Server Error.' });
        }
    };
};

