    public static function update_balance($user_id, $amount, $type = 'credit', $description = '', $reference = '')
    {
        global $wpdb;
        $table = $wpdb->prefix . 'wallet_transactions';

        $current_balance = self::get_balance($user_id);
        $amount = (float) $amount;

        if ($type === 'credit') {
            $new_balance = $current_balance + $amount;
        } elseif ($type === 'debit') {
            if ($current_balance < $amount) {
                return new WP_Error('insufficient_balance', __('Insufficient balance.', 'wp-wallet-system'));
            }
            $new_balance = $current_balance - $amount;
        } else {
            return new WP_Error('invalid_type', __('Invalid transaction type.', 'wp-wallet-system'));
        }

        $result = $wpdb->insert(
            $table,
            array(
                'user_id'        => $user_id,
                'type'           => $type,
                'amount'         => $amount,
                'balance_after'  => $new_balance,
                'description'    => $description,
                'status'         => 'completed',
                'reference'      => $reference,
                'created_at'     => current_time('mysql'),
            ),
            array('%d', '%s', '%f', '%f', '%s', '%s', '%s', '%s')
        );

        if (false === $result) {
            return new WP_Error('db_error', __('Database error occurred.', 'wp-wallet-system'));
        }

        update_user_meta($user_id, '_wallet_balance', $new_balance);
        return $new_balance;
    }

