// Program 1: Interactive Task Management System

// Declaration of the task array
let tasks = [];

// DOM element selection
const taskInput = document.getElementById('taskInput');
const addButton = document.getElementById('addButton');
const taskList = document.getElementById('taskList');

// Function to render the task array to the DOM
function renderTasks() {
    // Clear the existing list to prevent duplication
    taskList.innerHTML = '';

    // Iterate over the tasks array utilizing a forEach loop
    tasks.forEach((task, index) => {
        // Create a new list item element
        const li = document.createElement('li');
        li.textContent = task;

        // Instantiate a delete button for each task
        const deleteButton = document.createElement('button');
        deleteButton.textContent = 'Delete';
        deleteButton.addEventListener('click', () => {
            // Utilize splice to remove the specific task by index
            tasks.splice(index, 1);
            // Re-render the list subsequent to deletion
            renderTasks();
        });

        // Append the delete button to the list item, and the list item to the unordered list
        li.appendChild(deleteButton);
        taskList.appendChild(li);
    });
}

// Event listener for the addition of a new task
