    const newTask = taskInput.value.trim();

    // Conditional logic to prevent the addition of empty strings
    if (newTask !== '') {
        tasks.push(newTask);
        taskInput.value = ''; // Clear the input field
        renderTasks(); // Update the DOM
    }
});
