// Program 2: Stochastic Number Deduction Algorithm

// Generation of a pseudo-random integer between 1 and 100
const targetNumber = Math.floor(Math.random() * 100) + 1;
let userGuess = null;
let attemptCount = 0;

console.log("Algorithm Initialized: A random number between 1 and 100 has been generated.");

// Iterative loop that persists until the user's guess correlates with the target number
while (userGuess !== targetNumber) {
    // Prompt the user for input; in a browser environment, window.prompt is utilized
    const input = prompt("Enter your numerical guess (1-100):");

    // Data type coercion from string to integer
    userGuess = parseInt(input, 10);
    attemptCount++;

    // Conditional logic to evaluate the user's guess
    if (isNaN(userGuess)) {
        console.log("Error: Invalid input. Please enter a valid integer.");
    } else if (userGuess < targetNumber) {
        console.log("Feedback: The inputted value is too low. Increment your guess.");
    } else if (userGuess > targetNumber) {
        console.log("Feedback: The inputted value is too high. Decrement your guess.");
    } else {
        console.log(`Affirmation: Correct! The number ${targetNumber} was deduced in ${attemptCount} attempts.`);
    }
}
