// Program 3: Asynchronous Data Retrieval Utility

// Declaration of an asynchronous function utilizing the async keyword
async function fetchWeatherData(cityName) {
    // Utilization of a mock API endpoint for pedagogical purposes
    const apiUrl = `https://api.example.com/weather?city=${cityName}`;

    try {
        // Await the fulfillment of the fetch Promise
        const response = await fetch(apiUrl);

        // Conditional check to ensure the HTTP response status is successful
        if (!response.ok) {
            throw new Error(`HTTP Error: Status ${response.status}`);
        }

        // Parse the JSON response body into a JavaScript object
        const data = await response.json();

        // Extract and display the relevant meteorological data
        console.log(`Meteorological Data for ${cityName}:`);
        console.log(`Temperature: ${data.temperature}°C`);
        console.log(`Atmospheric Condition: ${data.condition}`);

    } catch (error) {
        // Catch block to handle any exceptions thrown during the asynchronous operation
        console.error(`Data retrieval failed: ${error.message}`);
    }
}

// Invocation of the asynchronous function
fetchWeatherData("London");
