const tf = require('@tensorflow/tfjs-node');

class DemandForecastModel {
    constructor() {
        this.model = null;
    }

    async init() {
        this.model = tf.sequential();
        this.model.add(tf.layers.dense({inputShape: [3], units: 16, activation: 'relu'}));
        this.model.add(tf.layers.dense({units: 8, activation: 'relu'}));
        this.model.add(tf.layers.dense({units: 1}));
        this.model.compile({optimizer: tf.train.adam(0.01), loss: 'meanSquaredError'});
    }

    async train() {
        // Dummy training data
        const xs = tf.tensor2d([
            [1, 1, 0], [2, 1, 0], [3, 1, 0], [4, 1, 0], [5, 1, 0], [6, 1, 1], [7, 1, 1],
            [1, 12, 1], [2, 12, 1], [3, 12, 0], [4, 12, 0], [5, 12, 0], [6, 12, 1], [7, 12, 1]
        ]);
        const ys = tf.tensor2d([
            [50], [60], [65], [70], [80], [120], [130],
            [140], [150], [100], [110], [120], [180], [190]
        ]);

        await this.model.fit(xs, ys, {epochs: 100});
        console.log('Model trained successfully.');
    }

    predict(input) {
        const tensor = tf.tensor2d([input]);
        const prediction = this.model.predict(tensor);
        return prediction.dataSync()[0];
    }
}

module.exports = new DemandForecastModel();
```

