```javascript
async function monitor() {
  // Poll for new followed users every 30 seconds
  setInterval(async () => {
    for (const username of usernames) {
      try {
        const userId = accounts[username];

        // Get the list of user IDs for the users the user is following
        const { data: following } = await client.get('friends/ids', { user_id: userId });
        const followingUserIds = following.ids;

        // Filter out the user IDs that are already being tracked for the current user
        const existingFollowedUserIds = userIDs[username] || [];
        const newFollowedUserIds = followingUserIds.filter(id => !existingFollowedUserIds.includes(id));

        if (newFollowedUserIds.length > 0) {
          // Construct intent links for each new followed user
          const intentLinks = newFollowedUserIds.map(id => `https://twitter.com/intent/user?user_id=${id}`);

          // Extract metadata from each Twitter page and construct Discord messages
          for (let i = 0; i < intentLinks.length; i++) {
            const metadata = await getTwitterMetadata(intentLinks[i]);

            if (metadata) {
              // Assuming metadata.title contains the username (e.g., "@username")
              // If it's just the display name, you might need to adjust the URL construction
              const followedUserUrl = `https://twitter.com/intent/user?user_id=${newFollowedUserIds[i]}`;

              // Construct the Discord message payload
              const messagePayload = {
                content: `**New followed user for ${username}:**\n${metadata.title}\n${metadata.description}\n${followedUserUrl}`,
                embeds: [{
                  image: {
                    url: metadata.image
                  }
                }]
              };

              // Send to Discord webhook
              await webhook.send(messagePayload);

              // Update tracking state
              lastFollowedUsers[`${username}_${newFollowedUserIds[i]}`] = {
                id: newFollowedUserIds[i],
                username: metadata.title
              };
            }
          }

          // Update the existingFollowedUserIds array
          userIDs[username] = followingUserIds;
        }
      } catch (error) {
        console.error(`Error monitoring followed users for ${username}:`, error);
      }
    }
  }, 30000); // 30 seconds

  console.log('Monitoring started...');
}
