#include <iostream>
#include <vector>
using namespace std;

// Recursive helper function for DFS traversal
void dfs_helper(vector<vector<int>>& graph, int node, vector<bool>& visited) {
    // Mark the current node as visited
    visited[node] = true;
    cout << node << " ";

    // Recur for all the adjacent vertices
    for (int i = 0; i < graph[node].size(); i++) {
        int adj = graph[node][i];
        if (!visited[adj]) {
            dfs_helper(graph, adj, visited);
        }
    }
}

// DFS traversal of the graph
void dfs(vector<vector<int>>& graph, int start) {
    vector<bool> visited(graph.size(), false);
    dfs_helper(graph, start, visited);
}

int main() {
    int V = 5;
    vector<vector<int>> graph(V);

    // Add edges
    graph[0].push_back(1);
    graph[0].push_back(2);
    graph[1].push_back(2);
    graph[2].push_back(0);
    graph[2].push_back(3);
    graph[3].push_back(3);

    cout << "DFS traversal starting from node 2:\n";
    dfs(graph, 2);

    return 0;
}
```

### How it works:
1. **`dfs` function**: Initializes a `visited` array to keep track of which nodes have been explored. It then calls the helper function starting from the given `start` node.
2. **`dfs_helper` function**: Marks the current node as visited, prints it, and then iterates through all its adjacent nodes. If an adjacent node hasn't been visited, it recursively calls itself on that node.
3. **Output**: Starting at node `2`, it goes to `0`, then to `1`, backtracks to `0`, tries `2` (already visited), backtracks to `2`, and finally visits `3`. The final output is `2 0 1 3`.

### Complexity:
* **Time Complexity**: $O(V + E)$, where $V$ is the number of vertices and $E$ is the number of edges. This is because the algorithm explores every vertex and every edge exactly once.
* **Space Complexity**: $O(V)$ for the `visited` array and the call stack during recursion.

