const roiFrame = document.getElementById('roiFrame');
const previewFrame = document.getElementById('previewFrame');

let isUpdating = false;

// 2. Function to clone the DOM into the preview
function updatePreview() {
    if (isUpdating) return;
    isUpdating = true;

    // requestAnimationFrame ensures we only update once per screen refresh 
    // (60fps max), preventing performance issues during rapid DOM manipulation.
    requestAnimationFrame(() => {
