// 3. Set up the MutationObserver
const observer = new MutationObserver((mutationsList, observer) => {
    // Whenever a mutation happens, trigger the update function
    updatePreview();
});

// 4. Start observing the ROI frame
// We watch for additions, removals, attribute changes, and text content changes
observer.observe(roiFrame, {
    childList: true,      // Observe direct children additions/removals
    subtree: true,        // Observe all descendants
    attributes: true,    // Observe attribute changes (e.g., class, style, src)
    characterData: true  // Observe text content changes
});

// Initial render to sync the preview immediately on load
updatePreview();
