## Approach 1: Simple — `preload="auto"` + `load()`

The browser's `preload="auto"` tells it to start buffering the video immediately. Calling `load()` forces it to begin right away.

```tsx
// app/page.tsx
'use client';

import { useEffect, useRef, useState } from 'react';

const VIDEO_URL = 'https://example.com/video.mp4';

export default function VideoPage() {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [buffered, setBuffered] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    // Force the browser to start loading immediately
    video.preload = 'auto';
    video.load();

    const onProgress = () => {
      // Check if we've buffered enough (e.g., first 5 seconds)
      if (video.buffered.length > 0) {
        const bufferedEnd = video.buffered.end(video.buffered.length - 1);
        if (bufferedEnd >= 5) {
          setBuffered(true);
        }
      }
    };

    video.addEventListener('progress', onProgress);
    return () => video.removeEventListener('progress', onProgress);
  }, []);

  return (
    <div>
      <p>{buffered ? '✅ First 5s cached' : '⏳ Buffering…'}</p>
      <video
        ref={videoRef}
        src={VIDEO_URL}
        preload="auto"
        controls
        width={640}
      />
    </div>
  );
}
```

**Pros:** Dead simple, no extra infrastructure.
**Cons:** The browser decides how much to buffer — you can't precisely control "only the first N seconds."

