 * Description: Reads a button on PD2 and lights an LED on PC0.
 * The button is wired between PD2 and Ground. 
 * We enable the internal pull-up resistor, so PD2 reads HIGH 
 * when unpressed, and LOW when pressed.
 */
#include <avr/io.h>
#include <util/delay.h>

int main(void) {
    // Configure PC0 as output (LED)
    DDRC |= (1 << PC0);

    // Configure PD2 as input (Button)
    DDRD &= ~(1 << PD2);

    // Enable internal pull-up resistor on PD2
    // We write a 1 to the PORT register for an input pin to enable the pull-up.
    PORTD |= (1 << PD2);

    while (1) {
        // Check if the button is pressed (PD2 reads LOW)
        // We invert the bit with ~ so that when PIND reads 0, the condition is true.
        if (!(PIND & (1 << PD2))) {
            // Button pressed: Turn ON LED
            PORTC |= (1 << PC0);
        } else {
            // Button not pressed: Turn OFF LED
            PORTC &= ~(1 << PC0);
        }
    }
}
