### Example 5: UART Serial Communication
This program initializes the UART hardware to transmit data at 9600 baud (assuming an 8MHz system clock) and sends the string "Hello AVR!" continuously.

```c
/*
 * Target: ATmega32
 * Description: Transmits "Hello AVR!" over UART serial communication.
 * Assumes an 8MHz system clock. Baud rate set to 9600.
 * UBRR calculation: (F_CPU / (16 * BAUD)) - 1 = (8000000 / (16 * 9600)) - 1 = 51
 */
#include <avr/io.h>
#include <util/delay.h>

#define F_CPU 8000000UL // Define CPU frequency for calculations
#define BAUD 9600
#define MYUBRR (F_CPU / 16 / BAUD) - 1

void UART_Init(unsigned int ubrr) {
    // Set baud rate by writing high byte first, then low byte
    UBRRH = (unsigned char)(ubrr >> 8);
    UBRRL = (unsigned char)ubrr;

    // Enable Transmitter (TXEN) and Receiver (RXEN)
    UCSRB = (1 << TXEN) | (1 << RXEN);

    // Set frame format: 8 data bits, no parity, 1 stop bit
    UCSRC = (1 << URSEL) | (1 << UCSZ1) | (1 << UCSZ0);
}

void UART_Transmit(unsigned char data) {
    // Wait for empty transmit buffer (UDRE flag becomes 1)
    while (!(UCSRA & (1 << UDRE)));

    // Put data into buffer, sends the data
    UDR = data;
}

int main(void) {
    UART_Init(MYUBRR); // Initialize UART with calculated UBRR value

    while (1) {
        // Send string "Hello AVR!"
        UART_Transmit('H');
        UART_Transmit('e');
        UART_Transmit('l');
        UART_Transmit('l');
        UART_Transmit('o');
        UART_Transmit(' ');
        UART_Transmit('A');
        UART_Transmit('V');
        UART_Transmit('R');
        UART_Transmit('!');
        UART_Transmit('\r'); // Carriage return
        UART_Transmit('\n'); // New line

        _delay_ms(1000); // Wait 1 second before sending again
    }
}
